{
  "title": "期末考试的赛博武侠",
  "scene": "长安城的古巷中，期末考试的钟声即将敲响，机器猫小Q在你的背包里轻声嘀咕：‘抓住那个隐藏在古剑中的秘密，它可能会有用。’你手持的古剑突然开口：‘剑内有机关，长安城西的竹林中藏着线索。’你面前有三条路：直走就是考场，左边是幽静小巷，右边是竹林深处。",
  "goal": "找到隐藏在古剑中的信息以应对期末考试",
  "clue": "古剑中的秘密，竹林中的线索",
  "choices": [
    {"id": "A", "text": "直走进入考场", "outcome": "考场的题超出预期，难度较大，但你还是勉强过关", "result": "partial", "next": "retry"},
    {"id": "B", "text": "拐进幽静小巷观察", "outcome": "小巷里只有几个流浪汉闲聊，没有发现异常", "result": "fail", "next": "retry"},
    {"id": "C", "text": "往竹林深处前行", "outcome": "你沿着竹林中的狭窄小径前进，发现了一块古碑，碑上刻有机关提示。仔细查看后，你发现了一个隐藏在古剑剑柄中的微小芯片，里面存储着解题的关键线索", "result": "success", "next": "next_level"}
  ]
}
